defineRouteMeta({
  openAPI: {
    tags: ["slskd"],
    summary: "Get slskd Soulseek credentials",
    description:
      "Returns the stored Soulseek username, whether a password is set, and whether those credentials were generated by TransMule (authenticated users).",
    responses: {
      200: { description: "Credentials info" },
      403: { description: "Authentication required" },
    },
  },
});

export default defineEventHandler((event) => {
  requireUser(event);

  return {
    username: getConfig("slskd_username") || "",
    hasPassword: !!getConfig("slskd_password"),
    // true while the credentials shown are the ones TransMule generated for a
    // first run, so the UI can tell the user they may swap in their own account.
    generated: getConfig("slskd_credentials_generated") === "1",
  };
});
